<?php
$pageTitle='Configurações'; require_once __DIR__ . '/includes/header.php';
$isAdmin = ($_SESSION['usuario_tipo']??'') === 'admin';
$isDemoUser = APP_ENV === 'demo' && ($_SESSION['usuario_login'] ?? '') === 'demo';
$canEdit = $isAdmin || $isDemoUser;
if ($_SERVER['REQUEST_METHOD']==='POST') { if(!$canEdit) { flash('error','Somente o administrador pode alterar as configurações.'); redirect('configuracoes.php'); } $days=array_intersect(['1','2','3','4','5','6','7'],$_POST['dias']??[]); $start=$_POST['hora_inicio']??''; $end=$_POST['hora_fim']??''; $titulo=trim($_POST['titulo_site']??'')?:'Reserva de Áreas'; if(!$days||!valid_time($start)||!valid_time($end)||$start >= $end) flash('error','Informe dias e um intervalo de horário válido.'); else { try { $logo=upload_image($_FILES['logo']??[], $_POST['logo_atual']??null); $before=history_snapshot($pdo,'configuracoes',1); $pdo->prepare('UPDATE configuracoes SET dias_permitidos=?, hora_inicio=?, hora_fim=?, titulo_site=?, logo=? WHERE id=1')->execute([implode(',',$days),$start,$end,$titulo,$logo]); history_log($pdo,'configuracoes',1,$before,history_snapshot($pdo,'configuracoes',1)); flash('success','Configurações atualizadas.'); redirect('configuracoes.php'); } catch(Throwable $e) { flash('error',$e->getMessage()); } } }
$config=$pdo->query('SELECT * FROM configuracoes WHERE id=1')->fetch(); $allowed=explode(',',$config['dias_permitidos']); $names=['1'=>'Segunda','2'=>'Terça','3'=>'Quarta','4'=>'Quinta','5'=>'Sexta','6'=>'Sábado','7'=>'Domingo'];
?><div class="row justify-content-center"><div class="col-lg-7"><div class="app-card"><h1 class="h3">Configurações da agenda</h1><p class="text-muted mb-4">Defina os dias e horários em que as reservas são permitidas.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="logo_atual" value="<?= e($config['logo']) ?>"><div class="row"><div class="col-md-7 mb-3"><label class="form-label">Título da página</label><input class="form-control" name="titulo_site" required value="<?= e($config['titulo_site']) ?>"></div><div class="col-md-5 mb-3"><label class="form-label">Logo</label><input class="form-control" type="file" name="logo" accept="image/jpeg,image/png,image/webp"><?php if($config['logo']): ?><div class="mt-2"><img src="uploads/<?= e($config['logo']) ?>" alt="Logo atual" style="height:32px"></div><?php endif; ?></div></div><label class="form-label">Dias permitidos</label><div class="d-flex flex-wrap gap-3 mb-4"><?php foreach($names as $id=>$name): ?><label class="form-check"><input class="form-check-input" type="checkbox" name="dias[]" value="<?= $id ?>" <?= in_array((string)$id,$allowed,true)?'checked':'' ?>> <?= $name ?></label><?php endforeach; ?></div><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Horário de início</label><input class="form-control" type="time" name="hora_inicio" value="<?= substr($config['hora_inicio'],0,5) ?>" required></div><div class="col-md-6 mb-4"><label class="form-label">Horário de término</label><input class="form-control" type="time" name="hora_fim" value="<?= substr($config['hora_fim'],0,5) ?>" required></div></div><button class="<?= $canEdit?'btn btn-gold':'btn btn-secondary' ?>" <?= $canEdit?'type="submit"':'type="button" onclick="alert(\'Somente o administrador pode alterar as configurações.\')"' ?>>Salvar configurações</button></form></div></div></div><?php require __DIR__ . '/includes/footer.php';
